// Package validate 提供全框架共用的 validator 單例
// app 在此註冊的自訂驗證規則，會同時被 pkg/context 的 c.BindInput（請求驗證）
// 與 pkg/contract 的合約驗證看見，避免兩處各自持有獨立的規則表
//
// 底層是 github.com/go-playground/validator/v10。它在幾種情況下以 panic 回報問題
// （validate 標籤打錯、註冊保留名稱）；這一層一律攔下改回 error。
//
// 規則要在程式啟動階段註冊：註冊與驗證同時進行不是並行安全的。
//
// @ai:generated by=claude-opus-4-6 date=2026-02-27
package validate

import (
	"errors"
	"fmt"
	"reflect"
	"strings"
	"sync"

	"github.com/go-playground/validator/v10"
)

var (
	once     sync.Once
	instance *validator.Validate

	// registerMu 讓註冊彼此互斥：validator 的規則表是普通的 map，兩個 goroutine 同時註冊會讓行程
	// 以 "concurrent map writes" 直接結束（無法 recover）。驗證不經過這把鎖，
	// 所以註冊仍然要在開始處理請求之前完成
	registerMu sync.Mutex
)

// ErrInvalidTag 表示 struct 的 validate 標籤本身有問題（規則名稱打錯、參數格式不對），
// 不是被驗證的資料不合格。Struct / Var 以它包裝 validator 的 panic
var ErrInvalidTag = errors.New("validate: invalid validate tag")

// nameTags 為錯誤訊息裡欄位名稱的來源，依序取第一個有值的 tag。
// 先前只看 json：query / form 綁定的欄位（form:"q"）回報成 Go 欄位名 Q，客戶端對不上自己送的參數
var nameTags = []string{"json", "form", "query", "uri"}

// Default 回傳全框架共用的 *validator.Validate 單例。
// 直接在它上面註冊規則不受這個套件的保護（覆寫檢查、panic 轉 error），一般請用本套件的函式
func Default() *validator.Validate {
	once.Do(func() {
		v := validator.New()
		v.RegisterTagNameFunc(fieldName)
		instance = v
	})
	return instance
}

// fieldName 回傳欄位在錯誤訊息裡的名稱：json → form → query → uri 的第一個有值者，都沒有時為 Go 欄位名。
// json 與 form 都有而且不同時以 json 為準
func fieldName(fld reflect.StructField) string {
	for _, tag := range nameTags {
		name := strings.SplitN(fld.Tag.Get(tag), ",", 2)[0]
		if name == "-" {
			continue
		}
		if name != "" {
			return name
		}
	}
	return ""
}

// guard 執行 fn 並把 validator 的 panic 轉成 error
func guard(fn func() error) (err error) {
	defer func() {
		if p := recover(); p != nil {
			err = fmt.Errorf("%v", p)
		}
	}()
	return fn()
}

// defined 回報規則或別名是否已存在（內建或先前註冊的）。
// validator 沒有查詢的 API：以空字串試驗，名稱不存在時它 panic "Undefined validation function"
func defined(tag string) bool {
	err := guard(func() error { Default().Var("", tag); return nil })
	return err == nil || !strings.Contains(err.Error(), "Undefined validation function")
}

// RegisterValidation 在共用實例上註冊自訂驗證規則，須於程式啟動階段呼叫。
//
// 名稱已存在（內建規則或先前註冊過）時回傳錯誤，不覆寫：先前 RegisterValidation("email", fn)
// 回 nil，之後整個框架的 email 規則都被換掉。真的要取代既有規則時用 OverrideValidation。
// 保留名稱（required、dive…）先前讓 validator 直接 panic，現在回傳錯誤
func RegisterValidation(tag string, fn validator.Func, callValidationEvenIfNull ...bool) error {
	registerMu.Lock()
	defer registerMu.Unlock()
	if tag != "" && fn != nil && defined(tag) {
		return fmt.Errorf("validate: rule %q already exists (built-in or registered earlier): use OverrideValidation to replace it", tag)
	}
	return register(tag, fn, callValidationEvenIfNull...)
}

// OverrideValidation 註冊驗證規則，名稱已存在時取代它（包含內建規則）。
// 取代的是整個框架共用的規則：BindInput 與 contract 都會改用新的函式。
// 要在那個規則第一次被使用之前呼叫（程式啟動階段）：validator 會快取解析過的標籤，
// 已經用過的標籤繼續呼叫舊的函式
func OverrideValidation(tag string, fn validator.Func, callValidationEvenIfNull ...bool) error {
	registerMu.Lock()
	defer registerMu.Unlock()
	return register(tag, fn, callValidationEvenIfNull...)
}

func register(tag string, fn validator.Func, callValidationEvenIfNull ...bool) error {
	err := guard(func() error { return Default().RegisterValidation(tag, fn, callValidationEvenIfNull...) })
	if err != nil {
		return fmt.Errorf("validate: register %q: %w", tag, err)
	}
	return nil
}

// RegisterAlias 為一組規則註冊別名（RegisterAlias("username", "required,min=3,max=20")），
// 須於程式啟動階段呼叫。別名已存在、是保留名稱，或 tags 用到不存在的規則時回傳錯誤。
// 先前沒有回傳值：保留名稱直接 panic，tags 打錯要等到第一次驗證才 panic
func RegisterAlias(alias, tags string) error {
	if alias == "" || tags == "" {
		return errors.New("validate: alias and tags must not be empty")
	}
	registerMu.Lock()
	defer registerMu.Unlock()
	if defined(alias) {
		return fmt.Errorf("validate: %q already exists as a rule or alias", alias)
	}
	if err := guard(func() error { Default().Var("", tags); return nil }); err != nil &&
		strings.Contains(err.Error(), "Undefined validation function") {
		return fmt.Errorf("validate: alias %q: %w", alias, err)
	}
	if err := guard(func() error { Default().RegisterAlias(alias, tags); return nil }); err != nil {
		return fmt.Errorf("validate: register alias %q: %w", alias, err)
	}
	return nil
}

// Struct 以共用規則表驗證 struct。
// 資料不合格時回傳 validator.ValidationErrors；validate 標籤本身有問題時回傳包著 ErrInvalidTag 的錯誤
// （先前是 panic：打錯的標籤要到第一個請求才發現，而且每個請求都 panic）
func Struct(s interface{}) error {
	return tagGuard(func() error { return Default().Struct(s) })
}

// Var 以共用規則表驗證單一變數；tag 用到不存在的規則時回傳包著 ErrInvalidTag 的錯誤
func Var(field interface{}, tag string) error {
	return tagGuard(func() error { return Default().Var(field, tag) })
}

func tagGuard(fn func() error) (err error) {
	defer func() {
		if p := recover(); p != nil {
			err = fmt.Errorf("%w: %v", ErrInvalidTag, p)
		}
	}()
	return fn()
}

// Issue 為 CheckType 找到的一個問題
type Issue struct {
	Kind    string // IssueInvalidTag 或 IssueMissingDive
	Field   string // 欄位路徑（Order.items）；整個型別的問題時為型別名稱
	Message string
}

// Issue 的種類
const (
	IssueInvalidTag  = "invalid_tag"  // validate 標籤無法使用：驗證時會失敗
	IssueMissingDive = "missing_dive" // slice / map 的元素有驗證規則，欄位卻沒有 dive：元素不會被驗證
)

// CheckType 檢查 v 的型別（及它用到的所有 struct）的 validate 標籤，不需要任何資料。
// 啟動時的 Schema Lint 以它檢查每條路由的 Input / Output：
//
//   - 標籤打錯（validate:"requried"）或參數不合規則
//   - 欄位是 struct 的 slice / array / map、元素帶有 validate 規則，欄位自己卻沒有 dive：
//     validator 不會進去驗證元素（巢狀 struct 與指標會自動驗證，只有集合不會）。
//     刻意不驗證元素時在欄位寫 validate:"-"
func CheckType(v interface{}) []Issue {
	t := reflect.TypeOf(v)
	var issues []Issue
	checkType(t, map[reflect.Type]bool{}, &issues)
	return issues
}

func checkType(t reflect.Type, seen map[reflect.Type]bool, issues *[]Issue) {
	if t = unwrap(t); t == nil || t.Kind() != reflect.Struct || seen[t] {
		return
	}
	seen[t] = true

	// 以零值驗證一次：validator 這時解析這個 struct 所有欄位的標籤，有問題就 panic
	if err := Struct(reflect.New(t).Elem().Interface()); errors.Is(err, ErrInvalidTag) {
		*issues = append(*issues, Issue{
			Kind: IssueInvalidTag, Field: t.String(),
			Message: strings.TrimPrefix(err.Error(), ErrInvalidTag.Error()+": "),
		})
	}

	for i := 0; i < t.NumField(); i++ {
		f := t.Field(i)
		if !f.IsExported() {
			continue
		}
		tag := f.Tag.Get("validate")
		if elem := collectionElem(f.Type); elem != nil && tag != "-" && !hasRule(tag, "dive") && hasRules(elem, map[reflect.Type]bool{}) {
			*issues = append(*issues, Issue{
				Kind: IssueMissingDive, Field: t.String() + "." + displayName(f),
				Message: fmt.Sprintf("elements of %s have validate rules but the field has no dive, so they are never validated: add validate:\"dive\" (or validate:\"-\" to skip them on purpose)", f.Type),
			})
		}
		if tag != "-" {
			checkType(f.Type, seen, issues)
		}
	}
}

// unwrap 解開指標與集合，回傳最裡面的型別。
// 自我參照的型別（type Tree []Tree）解不完：回到看過的型別時回傳 nil
func unwrap(t reflect.Type) reflect.Type {
	visited := map[reflect.Type]bool{}
	for t != nil {
		switch t.Kind() {
		case reflect.Ptr, reflect.Slice, reflect.Array, reflect.Map:
			if visited[t] {
				return nil
			}
			visited[t] = true
			t = t.Elem()
		default:
			return t
		}
	}
	return nil
}

// displayName 回傳欄位在訊息裡的名稱（同錯誤訊息的規則），沒有 tag 時為 Go 欄位名
func displayName(f reflect.StructField) string {
	if name := fieldName(f); name != "" {
		return name
	}
	return f.Name
}

// collectionElem 回傳 slice / array / map 的元素若為 struct（可隔著指標）時的 struct 型別，否則為 nil
func collectionElem(t reflect.Type) reflect.Type {
	for t.Kind() == reflect.Ptr {
		t = t.Elem()
	}
	if k := t.Kind(); k != reflect.Slice && k != reflect.Array && k != reflect.Map {
		return nil
	}
	elem := t.Elem()
	for elem.Kind() == reflect.Ptr && elem != t {
		elem = elem.Elem()
	}
	if elem.Kind() != reflect.Struct {
		return nil
	}
	return elem
}

// hasRule 回報 validate 標籤是否含指定的規則
func hasRule(tag, rule string) bool {
	for _, part := range strings.Split(tag, ",") {
		if strings.TrimSpace(part) == rule {
			return true
		}
	}
	return false
}

// hasRules 回報 struct（含巢狀）是否有任何 validate 規則
func hasRules(t reflect.Type, seen map[reflect.Type]bool) bool {
	if t = unwrap(t); t == nil || t.Kind() != reflect.Struct || seen[t] {
		return false
	}
	seen[t] = true
	for i := 0; i < t.NumField(); i++ {
		f := t.Field(i)
		if !f.IsExported() {
			continue
		}
		if tag := f.Tag.Get("validate"); tag != "" && tag != "-" {
			return true
		}
		if hasRules(f.Type, seen) {
			return true
		}
	}
	return false
}
